-- Deities and Demigods: Elishar and Toldoth divine stat blocks from Chapter 7.
-- Source: Deities and Demigods (2002), pp. 206-211, plus official v3.5 accessory update.
-- Printed 3.0 statistics remain source-of-truth; revision3_5 records revised-game execution deltas.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Five-pointed star containing a smaller five-pointed star'
WHERE slug='elishar' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Onyx disk'
WHERE slug='toldoth' AND owner_user_id IS NULL;

