INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
       'Use the structured mechanics payload for this deity. Printed 3.0 values remain source-of-truth; revision3_5 records official revised-game deltas and does not erase the source block.',
       0,NULL,1,'deity','divine-stat-block',0,1,'dd-following-the-light',NULL,
       '["deities-and-demigods","other-religions","following-the-light","deity-stat-block","revision-3.5"]',d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);